BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — One-third support test for public charity under Section 509(a)(1)
(3, 'Tax-Exempt Organizations', 'Riverside Education Alliance, a 501(c)(3) nonprofit, receives 45% of its total support from government grants and individual donations, with the remaining 55% from investment income and endowment returns. Under Section 509(a)(1), how is this organization classified?', '["Public charity, because it receives more than one-third of its support from public sources", "Private foundation, because investment income exceeds public support", "Public charity, because it received some government grants", "Private foundation, because it fails the one-third support test"]'::jsonb, 0, 'Under IRC Section 509(a)(1), an organization qualifies as a public charity if it receives a substantial part of its support from the general public or government—specifically, at least one-third. With 45% from public/government sources, Riverside exceeds the one-third threshold. Option D is incorrect because 45% clearly satisfies the one-third requirement, not fails it.', 'medium', 2),

-- Q2: medium / L2 — Controlled entity payments treated as UBIT
(3, 'Tax-Exempt Organizations', 'Lakewood Health Foundation, a 501(c)(3), owns 90% of MedSupply Corp. MedSupply pays $200,000 in annual rent to Lakewood for use of a building. Comparable fair market rent is $120,000. How is the $200,000 rental payment treated for UBIT purposes?', '["Entirely excluded as passive rental income from real property", "Only the $80,000 excess over fair market value is treated as UBIT", "The entire $200,000 is treated as UBIT because MedSupply is a controlled entity", "Only $120,000 is treated as UBIT because that is the fair market amount"]'::jsonb, 1, 'Under IRC Section 512(b)(13), rent received from a controlled subsidiary (80%+ ownership) is included in UBIT to the extent it exceeds fair market value. The $80,000 excess ($200,000 minus $120,000 FMV) is taxable as UBI. Option A is incorrect because the passive income exclusion does not apply to above-FMV payments from controlled entities.', 'medium', 2),

-- Q3: easy / L1 — Dissolution clause requirement
(3, 'Tax-Exempt Organizations', 'What must an organization''s governing documents provide regarding dissolution to satisfy the organizational test under Section 501(c)(3)?', '["Assets must be distributed to another exempt organization or to the government", "Assets must be distributed equally among the organization''s members", "Assets must be returned to the original donors", "Assets must be liquidated and deposited into a federal trust fund"]'::jsonb, 0, 'Under IRC Section 501(c)(3), the organizational test requires a dissolution clause providing that upon dissolution, remaining assets will be distributed to another exempt organization or to a governmental entity. Option B is incorrect because distribution to members would constitute private inurement, violating exempt status requirements.', 'easy', 1),

-- Q4: easy / L1 — Exempt purposes under Section 501(c)(3)
(3, 'Tax-Exempt Organizations', 'Which of the following is NOT a qualifying exempt purpose under Section 501(c)(3)?', '["Religious", "Charitable", "Commercial profit-making", "Scientific"]'::jsonb, 2, 'Under IRC Section 501(c)(3), qualifying exempt purposes include religious, charitable, scientific, educational, literary, testing for public safety, fostering amateur sports, and prevention of cruelty to children or animals. Commercial profit-making is not a qualifying purpose. Option A is incorrect because religious purposes are expressly listed as qualifying exempt purposes.', 'easy', 1),

-- Q5: hard / L4 — Supporting organization classification under Section 509(a)(3)
(3, 'Tax-Exempt Organizations', 'Healthcare Support Inc. was created exclusively to raise funds for City General Hospital, a public charity. Its board has 7 directors, 4 of whom are appointed by City General, and its articles restrict activities to supporting the hospital''s mission. The IRS is evaluating whether Healthcare Support qualifies as a public charity under Section 509(a)(3). Evaluate which factors are most critical to this classification.', '["Type I supporting organization, because City General controls Healthcare Support through majority board appointment", "Private foundation, because it supports only one organization", "Public charity under Section 509(a)(1), because it receives support from City General", "Type III supporting organization, because it has an independent board"]'::jsonb, 0, 'Under IRC Section 509(a)(3), a supporting organization qualifies as a public charity if operated exclusively to support one or more public charities. A Type I supporting organization is "operated, supervised, or controlled by" the supported organization, demonstrated by City General appointing a majority (4 of 7) of directors. Option B is incorrect because supporting a single public charity does not create private foundation status under the Section 509(a)(3) framework.', 'hard', 4),

-- Q6: medium / L2 — Personal property rents included in UBIT (above 10% threshold)
(3, 'Tax-Exempt Organizations', 'Mountainview Arts Council, a 501(c)(3), leases a building and office equipment to a local business under a single lease. Total annual rent is $100,000, of which $15,000 is attributable to the office equipment (personal property). How is the rental income treated for UBIT purposes?', '["The entire $100,000 is excluded as passive rental income", "The entire $100,000 is subject to UBIT because the lease includes personal property", "Only the $15,000 personal property portion is subject to UBIT", "The $15,000 personal property rent is excluded because it is less than 50% of total rents"]'::jsonb, 2, 'Under IRC Section 512(b)(3), rents from real property are excluded from UBIT, but rents from personal property are included unless incidental (less than 10% of total rents). Here, the personal property portion is $15,000/$100,000 = 15%, exceeding the 10% threshold, so the $15,000 personal property rent is subject to UBIT. Option A is incorrect because the personal property component exceeds the incidental threshold.', 'medium', 2),

-- Q7: easy / L1 — Section 501(h) expenditure test election
(3, 'Tax-Exempt Organizations', 'What does the Section 501(h) election allow a 501(c)(3) organization to do?', '["Engage in unlimited political campaign activity", "Avoid filing Form 990 for three consecutive years", "Distribute less than 5% of assets annually", "Use specific dollar thresholds as a safe harbor for lobbying expenditures"]'::jsonb, 3, 'Under IRC Section 501(h), eligible 501(c)(3) organizations may elect to use specific dollar-amount thresholds (based on exempt purpose expenditures) as a safe harbor for measuring permissible lobbying activity, replacing the subjective "substantial part" test. Option A is incorrect because political campaign activity remains absolutely prohibited regardless of any election.', 'easy', 1),

-- Q8: medium / L3 — Form 990 threshold determination
(3, 'Tax-Exempt Organizations', 'Westside Community Garden, a 501(c)(3), has gross receipts of $175,000 and total assets of $480,000 for the current year. Its treasurer is unsure which annual information return to file. Based on these thresholds, which form must Westside file?', '["Form 990-N (e-Postcard)", "Form 990-EZ (simplified return)", "Form 990 (full return)", "No filing is required for organizations of this size"]'::jsonb, 1, 'Under IRC Section 6033 and IRS filing thresholds, Form 990-EZ is used when gross receipts are less than $200,000 AND total assets are less than $500,000. Westside''s $175,000 in gross receipts and $480,000 in assets both fall below these thresholds, qualifying for 990-EZ. Option C is incorrect because the full Form 990 is required only when gross receipts reach $200,000 or total assets reach $500,000.', 'medium', 3),

-- Q9: medium / L3 — Convenience exclusion application
(3, 'Tax-Exempt Organizations', 'Central University, a 501(c)(3), operates a laundry facility on campus that washes uniforms and linens exclusively for students, faculty, and staff. A nearby competitor complains the laundry is an unfair tax-exempt business. Applying the UBIT three-part test and statutory exclusions, determine whether the laundry income is subject to UBIT.', '["Subject to UBIT because it is a regularly carried-on trade or business unrelated to education", "Subject to UBIT because doing laundry is not an educational activity", "The laundry is exempt because all university operations are tax-free", "Excluded from UBIT under the convenience exclusion because the service is for students, faculty, and employees"]'::jsonb, 3, 'Under IRC Section 513(a)(2), activities conducted primarily for the convenience of members, students, patients, or employees are excluded from UBIT. Because the laundry serves exclusively university students, faculty, and staff, the convenience exclusion applies. Option A is incorrect because even though the laundry meets the three-part test, the statutory convenience exclusion overrides the UBIT treatment.', 'medium', 3),

-- Q10: medium / L2 — Private inurement vs excessive private benefit
(3, 'Tax-Exempt Organizations', 'River Valley Outreach, a 501(c)(3), awards a $50,000 no-bid consulting contract to the sister of its board chair for website redesign services. The board chair''s sister has no other connection to the organization. Which prohibition does this arrangement most directly implicate?', '["The private inurement prohibition, because net earnings are benefiting an insider''s family member", "The excessive private benefit doctrine, because a non-insider is receiving a disproportionate benefit", "The self-dealing rules under Section 4941, because it involves a disqualified person", "The political campaign activity prohibition, because it diverts funds from exempt purposes"]'::jsonb, 0, 'Under IRC Section 501(c)(3), the private inurement prohibition bars any net earnings from inuring to the benefit of private shareholders or individuals—insiders and those closely related to them. The board chair''s sister, as a family member of an insider, triggers the inurement analysis. Option B is incorrect because the excessive private benefit doctrine applies to non-insiders; here the beneficiary is connected to a board insider.', 'medium', 2),

-- Q11: hard / L4 — Rebuttable presumption of reasonableness criteria
(3, 'Tax-Exempt Organizations', 'Clearwater Health Alliance, a 501(c)(4), hires a new CEO at a salary of $1,200,000. Before approval, the board''s independent compensation committee obtained salary surveys from three comparable healthcare nonprofits, documented its analysis in board minutes, and excluded conflicted board members from the vote. The IRS later questions the arrangement under Section 4958. Evaluate how the rebuttable presumption of reasonableness affects the IRS''s burden.', '["The IRS bears the burden of proving the compensation is excessive because all three elements of the rebuttable presumption were satisfied", "The organization bears the burden because the presumption only applies to 501(c)(3) organizations", "The rebuttable presumption does not apply because the salary exceeds $1,000,000", "The IRS can impose intermediate sanctions without burden-shifting because the salary is above market average"]'::jsonb, 0, 'Under IRC Section 4958 and Treasury Regulations, the rebuttable presumption of reasonableness applies to both 501(c)(3) and 501(c)(4) organizations when three conditions are met: (1) approval by an independent board, (2) reliance on appropriate comparability data, and (3) contemporaneous documentation. Clearwater met all three, shifting the burden to the IRS. Option B is incorrect because the presumption applies to 501(c)(4) organizations as well, not just 501(c)(3)s.', 'hard', 4),

-- Q12: medium / L3 — NOL deduction for UBIT
(3, 'Tax-Exempt Organizations', 'Heritage Preservation Society, a 501(c)(3), has $40,000 of unrelated business income and $55,000 of directly connected expenses in 2025, creating a $15,000 net operating loss. In 2026, the organization earns $30,000 of unrelated business income with $10,000 in expenses. Applying the UBIT NOL rules, determine Heritage''s 2026 unrelated business taxable income.', '["$19,000, because the full $30,000 is reduced by expenses and the specific deduction only", "$5,000, because the NOL reduces $20,000 net income to $5,000 with no further deduction", "$4,000, after applying the NOL carryforward and the $1,000 specific deduction", "$20,000, because prior-year losses cannot offset current-year UBI"]'::jsonb, 2, 'Under IRC Section 512(b)(6), NOLs from unrelated business activities carry forward and offset only UBI items. Heritage''s 2026 net UBI is $20,000 ($30,000 minus $10,000), reduced by the $15,000 NOL carryforward to $5,000, then reduced by the $1,000 specific deduction under Section 512(b)(12) to $4,000. Option B is incorrect because it omits the $1,000 specific deduction that applies after the NOL.', 'medium', 3),

-- Q13: easy / L1 — Form 990 filing deadline
(3, 'Tax-Exempt Organizations', 'What is the filing deadline for Form 990 for a calendar-year tax-exempt organization?', '["March 15", "April 15", "May 15", "June 15"]'::jsonb, 2, 'Under IRC Section 6033, Form 990 is due on the 15th day of the 5th month after the end of the organization''s tax year. For calendar-year organizations (year ending December 31), the deadline is May 15. Option B is incorrect because April 15 is the individual income tax return deadline, not the exempt organization information return deadline.', 'easy', 1),

-- Q14: medium / L2 — Automatic public charity classification (churches)
(3, 'Tax-Exempt Organizations', 'Grace Community Church receives 95% of its funding from a single wealthy donor family and only 5% from public contributions. Despite this concentrated funding source, Grace applies for 501(c)(3) status. How is the church classified?', '["Private foundation, because it fails the one-third public support test", "Public charity, because churches are automatically classified as public charities regardless of funding sources", "Private foundation, because a single donor provides substantially all support", "Public charity, but only if it elects under Section 509(a)(2)"]'::jsonb, 1, 'Under IRC Section 509(a)(1) and Section 170(b)(1)(A)(i), churches are automatically classified as public charities regardless of their funding sources. The one-third support test does not apply to churches, schools, or hospitals. Option A is incorrect because the public support test is not the basis for church classification—they qualify by organizational type alone.', 'medium', 2),

-- Q15: medium / L3 — Research exclusion from UBIT (non-university entity)
(3, 'Tax-Exempt Organizations', 'Pacific Medical Research Institute, a 501(c)(3) nonprofit (not a college, university, or hospital), conducts paid pharmaceutical research under contract with a private drug manufacturer. The results are proprietary and available only to the manufacturer. The institute also performs government-funded research with publicly available results. Applying the UBIT research exclusion, determine which research income is excluded.', '["Both contracts are excluded because all 501(c)(3) research furthers science", "Both contracts are subject to UBIT because the institute receives payment", "Only the government-funded research is excluded; the proprietary pharmaceutical research is subject to UBIT", "Only the pharmaceutical research is excluded because it involves scientific activity"]'::jsonb, 2, 'Under IRC Section 512(b)(7)-(9), research income is excluded from UBIT when performed for the government or when results are freely available to the public. The blanket exclusion for all research applies only to colleges, universities, and hospitals under Section 512(b)(8). Since Pacific is none of these, only its government-funded research qualifies. Option A is incorrect because the blanket research exclusion does not extend to all 501(c)(3) organizations.', 'medium', 3),

-- Q16: hard / L4 — Self-dealing correction and additional tax
(3, 'Tax-Exempt Organizations', 'The Johnson Family Foundation, a private foundation, leases office space from its founder for $60,000 annually at fair market rent. The foundation''s legal counsel discovers the lease two years later. The foundation manager approved the lease believing FMV terms made it permissible. Evaluate the tax consequences under Section 4941 if the foundation fails to unwind the lease within the correction period.', '["A 10% initial tax applies to the self-dealer, plus a 200% additional tax if uncorrected, because Section 4941 is a per se prohibition regardless of FMV", "No tax applies because the lease was negotiated at fair market value between the parties", "Only the 5% foundation manager tax applies because the self-dealer acted in good faith", "A 20% tax under Section 4945 applies because leasing property is classified as a taxable expenditure"]'::jsonb, 0, 'Under IRC Section 4941, self-dealing is determined by the nature of the transaction, not by whether the terms are arm''s length. Any lease between a private foundation and a disqualified person is prohibited. The initial tax is 10% on the self-dealer per year, with a 200% additional tax if not corrected. Option B is incorrect because FMV pricing does not exempt a transaction from the per se self-dealing prohibition.', 'hard', 4),

-- Q17: hard / L4 — Debt-financed income ratio calculation
(3, 'Tax-Exempt Organizations', 'Oakridge Education Foundation, a 501(c)(3), purchases a commercial building for $2,000,000, financing $1,200,000 with a mortgage. The building''s average adjusted basis is $1,800,000 and average acquisition indebtedness is $1,100,000. Annual rental income from commercial tenants is $180,000, with $60,000 in deductible expenses. Evaluate the debt-financed income calculation under Section 514.', '["$110,000, computed as 61.1% of $180,000 gross rental income", "$73,333, computed as 61.1% of the $120,000 net rental income", "The entire $180,000 is subject to UBIT because the property is debt-financed", "$120,000, the net rental income without applying the debt/basis ratio"]'::jsonb, 1, 'Under IRC Section 514, debt-financed income is subject to UBIT in proportion to average acquisition indebtedness divided by average adjusted basis: $1,100,000 / $1,800,000 = 61.1%. This ratio applies to net income: ($180,000 minus $60,000) x 61.1% = $73,333. Option C is incorrect because only the debt-financed proportion of net rental income is subject to UBIT, not the entire amount.', 'hard', 4),

-- Q18: medium / L2 — Section 4945 taxable expenditure (grants without IRS approval)
(3, 'Tax-Exempt Organizations', 'Greenfield Foundation, a private foundation, makes a $100,000 grant to an individual researcher without prior IRS approval of the grant procedures. Under Section 4945, how is this grant treated?', '["As a taxable expenditure subject to a 20% initial excise tax", "As a permissible charitable distribution counting toward the 5% minimum", "As a self-dealing transaction under Section 4941", "As an exempt activity because the grant furthers scientific research"]'::jsonb, 0, 'Under IRC Section 4945(d)(3), grants to individuals by a private foundation are taxable expenditures unless the foundation obtains advance IRS approval of its grant-making procedures. Without such approval, the $100,000 grant triggers a 20% initial excise tax. Option D is incorrect because the scientific purpose does not override the procedural requirement for individual grants under Section 4945.', 'medium', 2),

-- Q19: hard / L4 — Excess business holdings with combined disqualified persons
(3, 'Tax-Exempt Organizations', 'Palmer Family Foundation, a private foundation, owns 12% of the voting stock of Apex Industries. Palmer family members (disqualified persons) collectively own an additional 14%. Third-party investors own the remaining 74%. Evaluate whether the foundation has excess business holdings under Section 4943 and what corrective action is required.', '["The combined 26% holding exceeds the 20% permitted threshold, so the foundation must divest 6% to avoid a 10% excise tax on the excess", "No excess exists because the foundation directly holds only 12%, which is below 20%", "The 20% limit applies only to the foundation''s direct holdings, not combined holdings with disqualified persons", "The foundation must divest all 12% because any stock ownership by a private foundation is prohibited"]'::jsonb, 0, 'Under IRC Section 4943, a private foundation and its disqualified persons combined may not own more than 20% of the voting stock of a business enterprise. Palmer Foundation (12%) plus Palmer family (14%) equals 26%, exceeding the 20% limit by 6%. A 10% initial excise tax applies to the excess holdings. Option B is incorrect because Section 4943 aggregates both the foundation''s and disqualified persons'' holdings.', 'hard', 4),

-- Q20: easy / L1 — Form 990 late filing penalty
(3, 'Tax-Exempt Organizations', 'What is the daily penalty for failure to file Form 990 by a tax-exempt organization with gross receipts under $1,186,000?', '["$50 per day", "$100 per day", "$10 per day", "$20 per day"]'::jsonb, 3, 'Under IRC Section 6652(c)(1)(A), the penalty for failure to timely file Form 990 is $20 per day (up to $10,500 or 5% of gross receipts, whichever is less) for organizations with gross receipts under $1,186,000. Option B is incorrect because $100 per day applies only to larger organizations with gross receipts of $1,186,000 or more.', 'easy', 1),

-- Q21: medium / L3 — Bingo games exclusion criteria
(3, 'Tax-Exempt Organizations', 'Eastside Veterans Post, a 501(c)(3), hosts weekly bingo nights open to the public, charging $20 per player. A commercial bingo hall operates three blocks away in the same jurisdiction. Applying the UBIT bingo exclusion under Section 513(f), determine whether Eastside''s bingo income is excluded from UBIT.', '["Excluded, because bingo is always exempt for 501(c)(3) organizations", "Not excluded, because commercial bingo is ordinarily carried out in the same jurisdiction", "Excluded, because veterans'' organizations receive a blanket UBIT exemption", "Not excluded, because the activity charges admission fees"]'::jsonb, 1, 'Under IRC Section 513(f), bingo games are excluded from UBIT only when (1) they comply with state and local law and (2) commercial bingo is not ordinarily carried out in the same jurisdiction. Because a commercial bingo hall operates nearby, the exclusion does not apply. Option A is incorrect because the bingo exclusion is conditional on the absence of commercial bingo in the jurisdiction, not automatic.', 'medium', 3),

-- Q22: medium / L2 — Schedule B confidentiality
(3, 'Tax-Exempt Organizations', 'Advocates for Justice, a 501(c)(3), receives a public records request from a journalist asking for its complete Form 990 filing, including the Schedule of Contributors. Which portion of the filing is NOT available for public inspection?', '["Schedule A (Public Charity Status and Public Support)", "Schedule D (Supplemental Financial Statements)", "Schedule J (Compensation Information)", "Schedule B (Schedule of Contributors)"]'::jsonb, 3, 'Under IRC Section 6104, Form 990 is generally available for public inspection, but Schedule B (Schedule of Contributors) is confidential and not publicly available, protecting donor privacy. Option A is incorrect because Schedule A, which reports public charity status and public support calculations, is part of the publicly available return.', 'medium', 2),

-- Q23: easy / L1 — All 501(c)(3) organizations presumed to be private foundations
(3, 'Tax-Exempt Organizations', 'Under the Internal Revenue Code, how is a newly recognized 501(c)(3) organization initially classified?', '["As a public charity until proven otherwise", "As a supporting organization under Section 509(a)(3)", "Classification depends on the organization''s total assets at formation", "As a private foundation unless it demonstrates it qualifies as a public charity"]'::jsonb, 3, 'Under IRC Section 509(a), all 501(c)(3) organizations are presumed to be private foundations unless they affirmatively demonstrate they qualify as a public charity under one of the statutory exceptions (Sections 509(a)(1) through (4)). Option A is incorrect because the presumption runs the opposite direction—private foundation status is the default.', 'easy', 1),

-- Q24: easy / L1 — Section 4940 tax rate on net investment income
(3, 'Tax-Exempt Organizations', 'What is the excise tax rate imposed on a private foundation''s net investment income under Section 4940?', '["0.5%", "2%", "1.39%", "5%"]'::jsonb, 2, 'Under IRC Section 4940, private foundations are subject to a 1.39% excise tax on their net investment income, which includes interest, dividends, rents, royalties, and capital gains. Option B is incorrect because the 2% rate was the historical rate before it was simplified to a flat 1.39%.', 'easy', 1),

-- Q25: easy / L1 — Form 8868 extension for Form 990
(3, 'Tax-Exempt Organizations', 'What is the maximum extension period available for filing Form 990 using Form 8868?', '["3 months", "9 months", "6 months", "12 months"]'::jsonb, 2, 'Under IRC Section 6081 and Form 8868 procedures, an automatic extension of up to 6 months is available for filing Form 990 and other exempt organization returns. For a calendar-year organization with a May 15 deadline, this extends the due date to November 15. Option A is incorrect because the maximum automatic extension is 6 months, not 3 months.', 'easy', 1),

-- Q26: easy / L2 — Foundation manager tax rate for self-dealing
(3, 'Tax-Exempt Organizations', 'Atlas Foundation, a private foundation, purchases supplies from its founder''s company. The foundation''s executive director, who is not related to the founder, knowingly approves the purchase. Under Section 4941, what excise tax rate applies to the executive director as a foundation manager?', '["0%, because only the self-dealer is taxed", "10% of the amount involved", "25% of the amount involved", "5% of the amount involved"]'::jsonb, 3, 'Under IRC Section 4941(a)(2), a foundation manager who knowingly participates in a self-dealing transaction is subject to a 5% excise tax on the amount involved. This tax is separate from the 10% initial tax imposed on the self-dealer. Option B is incorrect because 10% is the rate imposed on the disqualified person who engaged in the self-dealing, not on the foundation manager.', 'easy', 2),

-- Q27: medium / L2 — Form 990-PF filing requirement for private foundations
(3, 'Tax-Exempt Organizations', 'Sterling Arts Foundation, a private foundation with $45,000 in gross receipts and $90,000 in total assets, asks its accountant whether it may file Form 990-EZ instead of Form 990-PF. What is the correct filing requirement?', '["Form 990-EZ is acceptable because gross receipts are under $200,000", "Form 990-N (e-Postcard) is sufficient because gross receipts are under $50,000", "No filing is required for private foundations with assets under $100,000", "Form 990-PF is required regardless of the foundation''s size"]'::jsonb, 3, 'Under IRC Section 6033 and IRS regulations, all private foundations must file Form 990-PF regardless of their size, gross receipts, or total assets. The Form 990, 990-EZ, and 990-N thresholds apply only to public charities and other non-foundation exempt organizations. Option A is incorrect because the 990-EZ option is not available to private foundations under any circumstances.', 'medium', 2),

-- Q28: hard / L3 — 200% additional tax on uncorrected excess benefit transaction
(3, 'Tax-Exempt Organizations', 'Pinnacle Community Alliance, a 501(c)(3), paid its former CFO a $400,000 severance package when comparable severance for similar positions was $100,000. The IRS determined the $300,000 excess constitutes an excess benefit transaction under Section 4958. The CFO fails to return the $300,000 within the correction period. Determine the total excise tax liability the CFO faces.', '["$75,000 (25% initial tax only)", "$600,000 (200% additional tax only)", "$150,000 (25% initial tax plus 25% additional tax)", "$675,000 ($75,000 initial tax plus $600,000 additional tax)"]'::jsonb, 3, 'Under IRC Section 4958, the initial tax on the disqualified person is 25% of the excess benefit ($300,000 x 25% = $75,000). If not corrected within the taxable period, an additional 200% tax applies ($300,000 x 200% = $600,000). Total liability is $675,000. Option B is incorrect because the 200% additional tax supplements rather than replaces the initial 25% tax.', 'hard', 3),

-- Q29: medium / L3 — Operational test and 40% commercial activity
(3, 'Tax-Exempt Organizations', 'Sunrise Literacy Project, a 501(c)(3), devotes 60% of its activities to free reading tutoring for low-income children and 40% to operating a commercial printing business whose profits fund the tutoring program. An IRS examiner reviews whether Sunrise satisfies the operational test. Applying the operational test, determine whether the commercial printing activity jeopardizes exempt status.', '["No, because using profits for charitable purposes makes any commercial activity substantially related", "No, because the organization is operated primarily for exempt purposes and the commercial activity is secondary", "Yes, because operating a commercial business automatically disqualifies an organization", "Yes, because 40% commercial activity exceeds the insubstantial part threshold"]'::jsonb, 3, 'Under IRC Section 501(c)(3), the operational test requires that an organization be operated primarily for exempt purposes, with non-exempt activities limited to an insubstantial part. Devoting 40% of activities to a commercial printing business likely exceeds the insubstantial threshold. Option A is incorrect because the fact that income is used for exempt purposes does not make the generating activity itself permissible under the operational test.', 'medium', 3),

-- Q30: medium / L3 — Incidental personal property rents threshold (under 10%)
(3, 'Tax-Exempt Organizations', 'Midtown Cultural Center, a 501(c)(3), leases a gallery building along with display cases and lighting equipment to an art dealer. Total annual rent under the single lease is $120,000, of which $9,000 is allocated to the personal property. Applying the UBIT rules for mixed leases, determine whether any portion of the rent is subject to UBIT.', '["The $9,000 personal property portion is subject to UBIT because it exceeds 10% of total rent", "The entire $120,000 is excluded because the personal property portion is incidental at 7.5%, below the 10% threshold", "The entire $120,000 is subject to UBIT because the lease includes personal property", "Only the $111,000 real property portion is excluded; the $9,000 is always taxable"]'::jsonb, 1, 'Under IRC Section 512(b)(3), rents from personal property are excluded from UBIT when the personal property rent is incidental—less than 10% of total rents under the lease. Here, $9,000 / $120,000 = 7.5%, which is below the 10% threshold, so the entire $120,000 is excluded. Option A is incorrect because 7.5% does not exceed the 10% incidental threshold.', 'medium', 3)
;

COMMIT;
